import { Button } from "../../../ui/button";
import { cn } from "../../../lib/utils";
import { IconCheck } from "@tabler/icons-react";
import { FoglampLink } from "../../../lib/link-context";

export type FeatureSectionProps = {
	eyebrow?: string;
	title: string;
	description: string;
	bullets?: string[];
	/** Page-owned visual (chart, flow, code, …). */
	visual: React.ReactNode;
	/** Which side the visual sits on at desktop; alternate down the page. */
	visualPosition?: "right" | "left";
	primaryCta?: { label: string; href: string };
	secondaryCta?: { label: string; href: string };
	/** Full Tailwind text-color class for the eyebrow + bullet checks. */
	accentClassName?: string;
};

export function FeatureSection({
	eyebrow,
	title,
	description,
	bullets,
	visual,
	visualPosition = "right",
	primaryCta,
	secondaryCta,
	accentClassName = "text-foreground",
}: FeatureSectionProps) {
	return (
		<section className="mx-auto grid w-full max-w-6xl items-center gap-10 px-5 sm:px-8 lg:grid-cols-2 lg:gap-16">
			<div
				className={cn(
					"flex flex-col gap-5",
					visualPosition === "left" && "lg:order-2",
				)}
			>
				{eyebrow && (
					<span
						className={cn(
							"text-sm font-semibold tracking-wide uppercase",
							accentClassName,
						)}
					>
						{eyebrow}
					</span>
				)}
				<h2 className="font-display text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
					{title}
				</h2>
				<p className="text-lg text-muted-foreground text-pretty">
					{description}
				</p>

				{bullets && bullets.length > 0 && (
					<ul className="flex flex-col gap-3">
						{bullets.map((b) => (
							<li key={b} className="flex items-start gap-2.5 text-sm">
								<IconCheck
									className={cn("mt-0.5 size-4 shrink-0", accentClassName)}
								/>
								<span className="text-foreground/90">{b}</span>
							</li>
						))}
					</ul>
				)}

				{(primaryCta || secondaryCta) && (
					<div className="mt-2 flex flex-wrap gap-3">
						{primaryCta && (
							<Button render={<FoglampLink href={primaryCta.href} />}>
								{primaryCta.label}
							</Button>
						)}
						{secondaryCta && (
							<Button
								variant="outline"
								render={<FoglampLink href={secondaryCta.href} />}
							>
								{secondaryCta.label}
							</Button>
						)}
					</div>
				)}
			</div>

			<div className={cn(visualPosition === "left" && "lg:order-1")}>
				{visual}
			</div>
		</section>
	);
}

"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full bg-clip-padding text-sm font-medium whitespace-nowrap transition-all hover:duration-150 outline-none select-none focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-ring/50 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-[1.5px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        default:
          "bg-neutral-800 dark:bg-neutral-100 shadow-[var(--custom-shadow-primary)] text-primary-foreground hover:bg-primary/80 dark:hover:bg-primary/90 [&_svg:not([class*='text-'])]:text-neutral-300 dark:[&_svg:not([class*='text-'])]:text-neutral-700",
        outline:
          "shadow-(--custom-outline-shadow) bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-card dark:hover:bg-muted [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        secondary:
          "bg-secondary shadow-[var(--custom-shadow-secondary)] text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground dark:hover:bg-muted-foreground/25 [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-300",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        // Like `ghost` (transparent at rest), but hover tints it red — bg and
        // icon/text both shift to the destructive color. For low-emphasis
        // delete affordances that only "arm" on hover.
        "ghost-destructive":
          "hover:bg-destructive/10 hover:text-destructive text-destructive focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:hover:bg-destructive/20 dark:focus-visible:ring-destructive/40",
        destructive:
          "bg-destructive/10 shadow-[var(--custom-shadow-destructive)] text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        // Underline stays rendered but transparent at rest, fading its opacity
        // in on hover — the base `transition-all` animates the decoration color.
        link: "text-foreground underline decoration-foreground/20 underline-offset-4 hover:decoration-foreground",
      },
      size: {
        xs: "h-6 gap-[4.5px] rounded-full px-2.5 text-xs in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-[11px]",
        sm: "h-7 gap-[5px] rounded-full px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-[9px] has-[>svg:last-child]:pr-[9px]",
        default:
          "h-8 gap-[5.5px] px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2.5 has-[>svg:last-child]:pr-2.5",
        lg: "h-8.5 gap-1.5 px-[15px] has-[>svg:first-child]:pl-3 has-[>svg:last-child]:pr-3 [&_svg:not([class*='size-'])]:size-3.5",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-full in-data-[slot=button-group]:rounded-full [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-8 rounded-full in-data-[slot=button-group]:rounded-full",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  children,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      // When `render` swaps in a non-button element (e.g. a Next.js
      // <Link>/<a>), it isn't a native <button>; tell Base UI so it applies the
      // right a11y semantics instead of warning. An explicit prop always wins.
      nativeButton={nativeButton ?? props.render === undefined}
      {...props}
    >
      {React.Children.map(children, (child) =>
        typeof child === "string" || typeof child === "number" ? (
          <span>{child}</span>
        ) : (
          child
        )
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };
